class Solution {
public:
    vector<int> transformArray(vector<int>& arr) {
        while (true) {
            vector<int> nxt = arr;
            bool changed = false;
            for (int i = 1; i + 1 < (int)arr.size(); i++) {
                if (arr[i] < arr[i-1] && arr[i] < arr[i+1]) { nxt[i]++; changed = true; }
                else if (arr[i] > arr[i-1] && arr[i] > arr[i+1]) { nxt[i]--; changed = true; }
            }
            arr = nxt;
            if (!changed) return arr;
        }
    }
};

